{"id":"16d33421-8853-444c-941c-2ea77d496f0f","inserted_at":"2026-07-03T21:10:04.930422+00:00","updated_at":"2026-07-03T21:10:04.930422+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- =========================================================================\r\n-- SETUP CIVIC LEADERBOARD & SEGNALAZIONI (LOGICA \"DUE TESTIMONI\")\r\n-- =========================================================================\r\n\r\n-- 0. Tabella scans (Storico delle interazioni/NFC/QR dell'utente)\r\nCREATE TABLE IF NOT EXISTS scans (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\r\n    poi_id UUID,\r\n    validated BOOLEAN DEFAULT false,\r\n    points_earned INT DEFAULT 0,\r\n    created_at TIMESTAMPTZ DEFAULT now()\r\n);\r\n\r\n-- 1. Tabella civic_reports (Distruggiamo la vecchia versione di test)\r\nDROP TABLE IF EXISTS civic_reports CASCADE;\r\n\r\nCREATE TABLE civic_reports (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\r\n    \r\n    -- Geofencing per Match Automatico\r\n    grid_cell_50m TEXT NOT NULL, -- es. \"40.473_17.234\" (troncato a 3 decimali)\r\n    \r\n    category TEXT NOT NULL CHECK (category IN ('barrier', 'degradation', 'lighting', 'accessibility', 'other')),\r\n    description TEXT,\r\n    latitude NUMERIC(10,8),\r\n    longitude NUMERIC(10,8),\r\n    photo_url TEXT,\r\n    \r\n    -- Logica \"Due Testimoni\"\r\n    status TEXT DEFAULT 'pending_match' CHECK (status IN (\r\n        'submitted',      -- appena inviata (legacy)\r\n        'pending_match',  -- in attesa di conferma incrociata\r\n        'confirmed',      -- match trovato! (in attesa di moderazione B2B)\r\n        'verified',       -- risolto/verificato da B2B\r\n        'expired',        -- passati 14 gg senza match\r\n        'rejected'        -- falso allarme\r\n    )),\r\n    \r\n    matched_report_id UUID REFERENCES civic_reports(id),\r\n    match_confidence NUMERIC, -- 0.0 a 1.0\r\n    points_awarded INT DEFAULT 0,\r\n    \r\n    created_at TIMESTAMPTZ DEFAULT now(),\r\n    updated_at TIMESTAMPTZ DEFAULT now()\r\n);\r\n\r\n-- 2. Indici per performance e matching\r\nCREATE INDEX idx_civic_reports_user ON civic_reports(user_id);\r\nCREATE INDEX idx_civic_reports_grid ON civic_reports(grid_cell_50m, category, status);\r\n\r\n-- 3. Trigger per aggiornare automaticamente updated_at\r\nCREATE OR REPLACE FUNCTION update_updated_at_column()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n    NEW.updated_at = now();\r\n    RETURN NEW;\r\nEND;\r\n$$ language 'plpgsql';\r\n\r\nCREATE TRIGGER update_civic_reports_updated_at\r\n    BEFORE UPDATE ON civic_reports\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION update_updated_at_column();\r\n\r\n-- 4. Funzione PL/pgSQL per Match Automatico \"Due Testimoni\" (Scadenza 14gg)\r\nCREATE OR REPLACE FUNCTION check_for_match()\r\nRETURNS TRIGGER AS $$\r\nDECLARE\r\n    match_id UUID;\r\nBEGIN\r\n    -- Cerca segnalazione simile nello stesso punto (stessa cella), stessa categoria\r\n    -- di un utente DIVERSO, negli ultimi 14 GIORNI.\r\n    SELECT id INTO match_id\r\n    FROM civic_reports\r\n    WHERE grid_cell_50m = NEW.grid_cell_50m\r\n      AND category = NEW.category\r\n      AND status = 'pending_match'\r\n      AND user_id != NEW.user_id\r\n      AND created_at > now() - interval '14 days'\r\n    ORDER BY created_at DESC\r\n    LIMIT 1;\r\n    \r\n    -- Se trovata, promuovi ENTRAMBE a 'confirmed'\r\n    IF match_id IS NOT NULL THEN\r\n        -- Aggiorna la segnalazione \"Gemella\" (vecchia)\r\n        UPDATE civic_reports \r\n        SET status = 'confirmed', \r\n            matched_report_id = NEW.id,\r\n            match_confidence = 0.9,\r\n            updated_at = now()\r\n        WHERE id = match_id;\r\n        \r\n        -- Aggiorna la NUOVA segnalazione\r\n        NEW.status := 'confirmed';\r\n        NEW.matched_report_id := match_id;\r\n        NEW.match_confidence := 0.9;\r\n        \r\n    ELSE\r\n        -- Nessun match trovato, resta in attesa\r\n        NEW.status := 'pending_match';\r\n    END IF;\r\n    \r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\nCREATE TRIGGER trigger_match_report\r\n    BEFORE INSERT ON civic_reports\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION check_for_match();\r\n\r\n\r\n-- 5. Vista leaderboard: Global Impact Score (calibrato e vivo a 7gg)\r\nDROP VIEW IF EXISTS global_impact_leaderboard;\r\nCREATE OR REPLACE VIEW global_impact_leaderboard AS\r\nSELECT \r\n    p.id AS user_id,\r\n    p.nickname,\r\n    p.total_co2,\r\n    p.total_tokens,\r\n    COALESCE(c.verified_reports, 0) AS verified_reports,\r\n    COALESCE(s.validated_scans_7d, 0) AS recent_scans,\r\n    \r\n    (COALESCE(s.validated_scans_7d, 0) * 1) +\r\n    (p.total_tokens * 0.1) +\r\n    (COALESCE(c.verified_reports, 0) * 5) +\r\n    (COALESCE(p.total_co2, 0) * 0.01) AS impact_score,\r\n    \r\n    ROW_NUMBER() OVER (ORDER BY \r\n        (COALESCE(s.validated_scans_7d, 0) * 1) +\r\n        (p.total_tokens * 0.1) +\r\n        (COALESCE(c.verified_reports, 0) * 5) +\r\n        (COALESCE(p.total_co2, 0) * 0.01) DESC\r\n    ) AS rank\r\nFROM profiles p\r\nLEFT JOIN (\r\n    SELECT user_id, COUNT(id) AS verified_reports\r\n    FROM civic_reports\r\n    WHERE status IN ('verified', 'confirmed') -- Ora premiamo anche se solo 'confermato' dai cittadini\r\n    GROUP BY user_id\r\n) c ON p.id = c.user_id\r\nLEFT JOIN (\r\n    SELECT user_id, COUNT(id) AS validated_scans_7d\r\n    FROM scans\r\n    WHERE validated = true\r\n      AND created_at > now() - interval '7 days'\r\n    GROUP BY user_id\r\n) s ON p.id = s.user_id\r\nORDER BY impact_score DESC;\r\n\r\n-- 6. Row Level Security (RLS) base per civic_reports\r\nALTER TABLE civic_reports ENABLE ROW LEVEL SECURITY;\r\n\r\nCREATE POLICY \"Users can read own reports\" \r\nON civic_reports FOR SELECT \r\nUSING (auth.uid() = user_id);\r\n\r\nCREATE POLICY \"Users can insert own reports\" \r\nON civic_reports FOR INSERT \r\nWITH CHECK (auth.uid() = user_id);","content_id":"16d33421-8853-444c-941c-2ea77d496f0f","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
